using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a default resolver so common types are known.
var options = new JsonSerializerOptions
{
    TypeInfoResolver = JsonSerializer.IsReflectionEnabledByDefault
        ? new DefaultJsonTypeInfoResolver()
        : JsonSerializerContext.Default
};

// 1️⃣  Strongly-typed metadata — GetTypeInfo<T>() returns JsonTypeInfo<T> directly.
JsonTypeInfo<int[]> arrayMeta = (JsonTypeInfo<int[]>)options.GetTypeInfo(typeof(int[]));
Console.WriteLine($"Type  : {arrayMeta.Type.Name}");
Console.WriteLine($"Kind  : {arrayMeta.Kind}");
Console.WriteLine();

// 2️⃣  Probe without throwing — TryGetTypeInfo gives back false when the
//     resolver can't produce metadata for the requested type, instead of
//     throwing InvalidOperationException / NotSupportedException.
if (options.TryGetTypeInfo(typeof(string), out JsonTypeInfo? stringMeta))
{
    Console.WriteLine($"string metadata found — Kind: {stringMeta!.Kind}");
}
else
{
    Console.WriteLine("string metadata NOT available");
}

// A type the resolver might not know about (when using a source-gen context
// that wasn't told about it). With DefaultJsonTypeInfoResolver reflection
// is used, so it will succeed; swap in a limited context to see "not available".
if (options.TryGetTypeInfo(typeof(Version), out JsonTypeInfo? versionMeta))
{
    Console.WriteLine($"Version metadata found — Kind: {versionMeta!.Kind}");
}
else
{
    Console.WriteLine("Version metadata NOT available");
}

// 3️⃣  Demonstrate a resolver that genuinely lacks a type.
var limited = new JsonSerializerOptions { TypeInfoResolver = new LimitedResolver() };

if (limited.TryGetTypeInfo(typeof(double), out _))
    Console.WriteLine("double metadata found (unexpected)");
else
    Console.WriteLine("double metadata NOT available (expected — resolver is empty)");

// Minimal resolver that resolves nothing.
file class LimitedResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

